// The reader half of this repository's own generator (Phase 2299): the wire
// corpus's published `idl.json`, read into a small typed model. The IDL is the
// language-neutral data rendering of the wire vocabulary; nothing here is shared
// with, or generated by, any other tier.

import Foundation

/// A failure the generator reports instead of writing a model: an IDL it cannot
/// read, or a dialect entry that has stopped being true.
public struct IdlCodegenError: Error, CustomStringConvertible {
  public let message: String
  public init(_ message: String) { self.message = message }
  public var description: String { message }
}

/// An IDL field type (`idl.json` `$type`).
indirect enum IdlType: Equatable {
  case str, int, float, bool, json, node, kind, op
  case list(IdlType)
  case map(IdlType)
  case enumRef(String)
  case record(String)
  case union(String, [IdlType])
  case typeVar(String)
  /// A host-declared type whose wire shape is `wire` (`nil` = arbitrary JSON).
  case hosted(IdlType?)
  /// A closure slot: on the wire only the `"<closure>"` presence sentinel.
  case fn
}

/// How a field is present on the wire.
enum IdlOptionality: Equatable {
  case required
  case optional
  /// Omitted on the wire at `default` (the raw IDL default value object).
  case omitDefault(IdlDefault)
  /// Never on the wire.
  case hostOnly
}

/// A declared omit-at-default value.
indirect enum IdlDefault: Equatable {
  case bool(Bool)
  case int(Int)
  case float(Double)
  case str(String)
  case enumCase(String)
  case list([IdlDefault])
  case unionCase(tag: String, fields: [(String, IdlDefault)])
  case record([(String, IdlDefault)])

  static func == (l: IdlDefault, r: IdlDefault) -> Bool { "\(l)" == "\(r)" }
}

struct IdlField {
  let name: String
  let optionality: IdlOptionality
  let type: IdlType
}

struct IdlKind {
  let tag: String
  let category: String
  let fields: [IdlField]
}

struct IdlRecord {
  let name: String
  let fields: [IdlField]
}

struct IdlCase {
  let tag: String
  let fields: [IdlField]
}

struct IdlUnion {
  let name: String
  let params: [String]
  let cases: [IdlCase]
}

struct IdlEnum {
  let name: String
  /// The wire spellings.
  let cases: [String]
  /// The IDL's host case names, where the wire token is not one (`eq` → `Eq`).
  let hostCases: [String]?
}

struct Idl {
  let kinds: [IdlKind]
  let records: [IdlRecord]
  let unions: [IdlUnion]
  let enums: [IdlEnum]
  let nodeFields: [IdlField]

  func record(_ name: String) -> IdlRecord? { records.first { $0.name == name } }
  func union(_ name: String) -> IdlUnion? { unions.first { $0.name == name } }
  func enumeration(_ name: String) -> IdlEnum? { enums.first { $0.name == name } }
  func kind(_ tag: String) -> IdlKind? { kinds.first { $0.tag == tag } }
}

// ── Reading ────────────────────────────────────────────────────────────────

enum IdlReader {
  static func read(_ bytes: Data) throws -> Idl {
    let root: Any
    do {
      root = try JSONSerialization.jsonObject(with: bytes, options: [])
    } catch {
      throw IdlCodegenError("idl.json is not JSON: \(error)")
    }
    guard let o = root as? [String: Any] else {
      throw IdlCodegenError("idl.json root is not an object")
    }
    return Idl(
      kinds: try arr(o, "kinds", "idl").map { j in
        let k = try obj(j, "kinds[]")
        let tag = try str(k, "tag", "kinds[]")
        return IdlKind(
          tag: tag, category: try str(k, "category", "kind \(tag)"),
          fields: try fields(k, "kind \(tag)"))
      },
      records: try arr(o, "records", "idl").map { j in
        let r = try obj(j, "records[]")
        let name = try str(r, "name", "records[]")
        return IdlRecord(name: name, fields: try fields(r, "record \(name)"))
      },
      unions: try arr(o, "unions", "idl").map { j in
        let u = try obj(j, "unions[]")
        let name = try str(u, "name", "unions[]")
        let params = (u["params"] as? [Any])?.compactMap { $0 as? String } ?? []
        let cases = try arr(u, "cases", "union \(name)").map { c -> IdlCase in
          let co = try obj(c, "union \(name) case")
          let tag = try str(co, "tag", "union \(name) case")
          return IdlCase(tag: tag, fields: try fields(co, "union \(name).\(tag)"))
        }
        return IdlUnion(name: name, params: params, cases: cases)
      },
      enums: try arr(o, "enums", "idl").map { j in
        let e = try obj(j, "enums[]")
        let name = try str(e, "name", "enums[]")
        let cases = try arr(e, "cases", "enum \(name)").map { c -> String in
          guard let s = c as? String else {
            throw IdlCodegenError("enum \(name): a non-string case")
          }
          return s
        }
        let host = (e["hostCases"] as? [Any])?.compactMap { $0 as? String }
        if let host, host.count != cases.count {
          throw IdlCodegenError("enum \(name): hostCases and cases differ in length")
        }
        return IdlEnum(name: name, cases: cases, hostCases: host)
      },
      nodeFields: try fields(o, "nodeFields", key: "nodeFields"))
  }

  static func obj(_ j: Any, _ at: String) throws -> [String: Any] {
    guard let o = j as? [String: Any] else { throw IdlCodegenError("\(at): expected an object") }
    return o
  }

  static func arr(_ o: [String: Any], _ key: String, _ at: String) throws -> [Any] {
    guard let a = o[key] as? [Any] else { throw IdlCodegenError("\(at): '\(key)' is not an array") }
    return a
  }

  static func str(_ o: [String: Any], _ key: String, _ at: String) throws -> String {
    guard let s = o[key] as? String else {
      throw IdlCodegenError("\(at): '\(key)' is not a string")
    }
    return s
  }

  static func fields(_ o: [String: Any], _ at: String, key: String = "fields") throws -> [IdlField]
  {
    try arr(o, key, at).map { j in
      let f = try obj(j, "\(at) field")
      let name = try str(f, "name", "\(at) field")
      let here = "\(at).\(name)"
      let opt = try obj(f["optionality"] as Any, "\(here) optionality")
      let optionality: IdlOptionality
      switch try str(opt, "$type", "\(here) optionality") {
      case "required": optionality = .required
      case "optional": optionality = .optional
      case "hostOnly": optionality = .hostOnly
      case "omitDefault": optionality = .omitDefault(try defaultValue(opt["default"] as Any, here))
      case let other: throw IdlCodegenError("\(here): unknown optionality '\(other)'")
      }
      return IdlField(name: name, optionality: optionality, type: try type(f["type"] as Any, here))
    }
  }

  static func type(_ j: Any, _ at: String) throws -> IdlType {
    let t = try obj(j, "\(at) type")
    switch try str(t, "$type", "\(at) type") {
    case "str": return .str
    case "int": return .int
    case "float": return .float
    case "bool": return .bool
    case "json": return .json
    case "node": return .node
    case "kind": return .kind
    case "op": return .op
    case "fn": return .fn
    case "list": return .list(try type(t["of"] as Any, "\(at)[]"))
    case "map": return .map(try type(t["values"] as Any, "\(at){}"))
    case "enum": return .enumRef(try str(t, "name", at))
    case "record": return .record(try str(t, "name", at))
    case "var": return .typeVar(try str(t, "name", at))
    case "union":
      let args = try ((t["args"] as? [Any]) ?? []).map { try type($0, "\(at)<>") }
      return .union(try str(t, "name", at), args)
    case "hosted":
      if let w = t["wire"] as? [String: Any] { return .hosted(try type(w, "\(at) wire")) }
      return .hosted(nil)
    case let other: throw IdlCodegenError("\(at): unknown type '\(other)'")
    }
  }

  static func defaultValue(_ j: Any, _ at: String) throws -> IdlDefault {
    let d = try obj(j, "\(at) default")
    switch try str(d, "$type", "\(at) default") {
    case "bool":
      guard let b = d["value"] as? Bool else { throw IdlCodegenError("\(at): bool default") }
      return .bool(b)
    case "int":
      guard let n = d["value"] as? NSNumber else { throw IdlCodegenError("\(at): int default") }
      return .int(n.intValue)
    case "float":
      guard let n = d["value"] as? NSNumber else { throw IdlCodegenError("\(at): float default") }
      return .float(n.doubleValue)
    case "str":
      return .str(try str(d, "value", at))
    case "enum":
      return .enumCase(try str(d, "case", at))
    case "list":
      return .list(try ((d["items"] as? [Any]) ?? []).map { try defaultValue($0, "\(at)[]") })
    case "union":
      return .unionCase(tag: try str(d, "tag", at), fields: try namedDefaults(d, at))
    case "record":
      return .record(try namedDefaults(d, at))
    case let other: throw IdlCodegenError("\(at): unknown default '\(other)'")
    }
  }

  static func namedDefaults(_ d: [String: Any], _ at: String) throws -> [(String, IdlDefault)] {
    try ((d["fields"] as? [Any]) ?? []).map { j in
      let f = try obj(j, "\(at) default field")
      let name = try str(f, "name", "\(at) default field")
      return (name, try defaultValue(f["value"] as Any, "\(at).\(name)"))
    }
  }
}

// ── SHA-256 (FIPS 180-4), so the generated file can name the IDL it came from ──

enum Sha256 {
  private static let k: [UInt32] = [
    0x428a_2f98, 0x7137_4491, 0xb5c0_fbcf, 0xe9b5_dba5, 0x3956_c25b, 0x59f1_11f1, 0x923f_82a4,
    0xab1c_5ed5, 0xd807_aa98, 0x1283_5b01, 0x2431_85be, 0x550c_7dc3, 0x72be_5d74, 0x80de_b1fe,
    0x9bdc_06a7, 0xc19b_f174, 0xe49b_69c1, 0xefbe_4786, 0x0fc1_9dc6, 0x240c_a1cc, 0x2de9_2c6f,
    0x4a74_84aa, 0x5cb0_a9dc, 0x76f9_88da, 0x983e_5152, 0xa831_c66d, 0xb003_27c8, 0xbf59_7fc7,
    0xc6e0_0bf3, 0xd5a7_9147, 0x06ca_6351, 0x1429_2967, 0x27b7_0a85, 0x2e1b_2138, 0x4d2c_6dfc,
    0x5338_0d13, 0x650a_7354, 0x766a_0abb, 0x81c2_c92e, 0x9272_2c85, 0xa2bf_e8a1, 0xa81a_664b,
    0xc24b_8b70, 0xc76c_51a3, 0xd192_e819, 0xd699_0624, 0xf40e_3585, 0x106a_a070, 0x19a4_c116,
    0x1e37_6c08, 0x2748_774c, 0x34b0_bcb5, 0x391c_0cb3, 0x4ed8_aa4a, 0x5b9c_ca4f, 0x682e_6ff3,
    0x748f_82ee, 0x78a5_636f, 0x84c8_7814, 0x8cc7_0208, 0x90be_fffa, 0xa450_6ceb, 0xbef9_a3f7,
    0xc671_78f2,
  ]

  static func hex(_ data: Data) -> String {
    var h: [UInt32] = [
      0x6a09_e667, 0xbb67_ae85, 0x3c6e_f372, 0xa54f_f53a, 0x510e_527f, 0x9b05_688c, 0x1f83_d9ab,
      0x5be0_cd19,
    ]
    var msg = [UInt8](data)
    let bitLen = UInt64(msg.count) * 8
    msg.append(0x80)
    while msg.count % 64 != 56 { msg.append(0) }
    for i in (0..<8).reversed() { msg.append(UInt8((bitLen >> (UInt64(i) * 8)) & 0xff)) }
    var w = [UInt32](repeating: 0, count: 64)
    for chunk in stride(from: 0, to: msg.count, by: 64) {
      for i in 0..<16 {
        let b = chunk + i * 4
        w[i] =
          UInt32(msg[b]) << 24 | UInt32(msg[b + 1]) << 16 | UInt32(msg[b + 2]) << 8
          | UInt32(msg[b + 3])
      }
      for i in 16..<64 {
        let s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3)
        let s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10)
        w[i] = w[i - 16] &+ s0 &+ w[i - 7] &+ s1
      }
      var (a, b, c, d, e, f, g, hh) = (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7])
      for i in 0..<64 {
        let s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)
        let ch = (e & f) ^ (~e & g)
        let t1 = hh &+ s1 &+ ch &+ k[i] &+ w[i]
        let s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)
        let maj = (a & b) ^ (a & c) ^ (b & c)
        let t2 = s0 &+ maj
        hh = g
        g = f
        f = e
        e = d &+ t1
        d = c
        c = b
        b = a
        a = t1 &+ t2
      }
      h[0] = h[0] &+ a
      h[1] = h[1] &+ b
      h[2] = h[2] &+ c
      h[3] = h[3] &+ d
      h[4] = h[4] &+ e
      h[5] = h[5] &+ f
      h[6] = h[6] &+ g
      h[7] = h[7] &+ hh
    }
    return h.map { word in
      let s = String(word, radix: 16)
      return String(repeating: "0", count: 8 - s.count) + s
    }.joined()
  }

  private static func rotr(_ x: UInt32, _ n: UInt32) -> UInt32 { (x >> n) | (x << (32 - n)) }
}
